import { LANGUAGE_PROMPT_SUPPRESSION_DAYS } from './regionPrefCookie';

/**
 * The one real-world SFCC site ID shared by all four EU-domestic PWA sites (`ZimmermannEUen`,
 * `ZimmermannEUfr`, `ZimmermannEUit`, `ZimmermannEUes` — see `config/sites.overlay.js`). A
 * single equality check against this covers all four and naturally excludes EU International
 * (`ZimmermannEUIntl`, its own separate SFCC site, English-only), which has no `sfccSiteId`
 * override and so never carries this value.
 */
export const EU_DOMESTIC_SFCC_SITE_ID = 'ZimmermannEU';

/**
 * Primary-subtag language codes of the four EU-domestic sites' own locales (`en-GB`, `fr`,
 * `it`, `es` — `config/sites.overlay.js`). This predicate has no site config of its own to
 * derive the list from (it only receives already-extracted strings), so the four are named here
 * directly rather than threaded through as a parameter nothing else currently needs.
 */
export const SUPPORTED_EU_LANGUAGES: readonly string[] = ['en', 'fr', 'it', 'es'];

const SECONDS_PER_DAY = 24 * 60 * 60;

export type ShouldShowLanguagePromptInput = {
  /** The runtime's current PWA site's SFCC site id (e.g. `site.sfccSiteId`), or `undefined`. */
  readonly sfccSiteId: string | undefined;
  /** The current site's own language — a locale id/alias, e.g. `'fr'` or `'en-GB'`. */
  readonly currentLanguage: string;
  /** `navigator.languages`, most-preferred first, e.g. `['fr-FR', 'en-US']`. */
  readonly browserLanguages: readonly string[];
  /** The `l` value from `regionPrefCookie.ts`, in epoch **seconds** — `undefined` if never set. */
  readonly suppressedAt: number | undefined;
  /** The current time, in epoch **seconds** (same unit as `suppressedAt`). */
  readonly now: number;
};

export type ShouldShowLanguagePromptResult =
  | { readonly show: true; readonly targetLanguage: string }
  | { readonly show: false };

/** Lower-cases and takes the primary subtag of a BCP-47-ish tag: `'fr-FR'` -> `'fr'`. */
function primarySubtag(languageTag: string): string {
  return languageTag.split('-')[0].toLowerCase();
}

/**
 * Pure predicate for the EU-domestic language-mismatch prompt (SFCC-689). Decides whether the
 * shopper's browser language disagrees with the storefront they're currently on, and if so,
 * which of the four EU languages to offer switching to.
 *
 * Both sides of the comparison are reduced to their primary subtag before comparing — browsers
 * report full tags (`fr-FR`, `it-CH`), and one of our own site locales is itself a full tag
 * (`en-GB`) rather than a bare code. Comparing full strings would make a French shopper
 * reporting `fr-FR` never match anything, and would make `en-GB` (our own English site's
 * locale) never match a browser reporting plain `en`.
 *
 * Only `browserLanguages[0]` (the browser's single most-preferred language) is evaluated, not
 * the full preference list — every branch this predicate needs to support describes "the
 * browser's language" as one signal, and scanning further down an unmatched preference list for
 * a supported one is a behaviour nothing has specified.
 *
 * The suppression window is enforced here, at read time, against `suppressedAt` +
 * `LANGUAGE_PROMPT_SUPPRESSION_DAYS` — not by the cookie's own expiry (see `regionPrefCookie.ts`).
 */
export function shouldShowLanguagePrompt(input: ShouldShowLanguagePromptInput): ShouldShowLanguagePromptResult {
  const { sfccSiteId, currentLanguage, browserLanguages, suppressedAt, now } = input;

  if (sfccSiteId !== EU_DOMESTIC_SFCC_SITE_ID) {
    return { show: false };
  }

  if (suppressedAt !== undefined) {
    const suppressionWindowEnd = suppressedAt + LANGUAGE_PROMPT_SUPPRESSION_DAYS * SECONDS_PER_DAY;
    if (now < suppressionWindowEnd) {
      return { show: false };
    }
  }

  const browserLanguage = browserLanguages[0];
  if (!browserLanguage) {
    return { show: false };
  }

  const browserPrimary = primarySubtag(browserLanguage);
  if (browserPrimary === primarySubtag(currentLanguage)) {
    return { show: false };
  }

  if (SUPPORTED_EU_LANGUAGES.includes(browserPrimary)) {
    return { show: true, targetLanguage: browserPrimary };
  }

  return { show: false };
}

